SELECT 'printings' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.card_printings t WHERE id=ANY(ARRAY['a00039a3-9121-49a7-b6d1-f2ec4a7d5608']::uuid[]) UNION ALL SELECT 'variants',id::text,to_jsonb(t) FROM catalog.card_variants t WHERE printing_id=ANY(ARRAY['a00039a3-9121-49a7-b6d1-f2ec4a7d5608']::uuid[]) UNION ALL SELECT 'names',id::text,to_jsonb(t) FROM catalog.card_names t WHERE printing_id=ANY(ARRAY['a00039a3-9121-49a7-b6d1-f2ec4a7d5608']::uuid[]) OR variant_id=ANY(ARRAY['7699421e-d760-4251-a090-40166235602b']::uuid[]) UNION ALL SELECT 'sets',id::text,to_jsonb(t) FROM catalog.sets t WHERE id=ANY(ARRAY['e60f305b-5ad6-4964-b6c6-636788481ca5']::uuid[]) UNION ALL SELECT 'sources',id::text,to_jsonb(t) FROM ingest.sources t WHERE (code IN ('scrydex','pokellector','tcgcollector','pricecharting') OR lower(base_url) LIKE '%pokellector.com%' OR lower(base_url) LIKE '%tcgcollector.com%' OR lower(base_url) LIKE '%pricecharting.com%') UNION ALL SELECT 'assets',id::text,to_jsonb(t) FROM catalog.assets t WHERE printing_id=ANY(ARRAY['a00039a3-9121-49a7-b6d1-f2ec4a7d5608']::uuid[]) OR variant_id=ANY(ARRAY['7699421e-d760-4251-a090-40166235602b']::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['e60f305b-5ad6-4964-b6c6-636788481ca5']::uuid[])) UNION ALL SELECT 'links',catalogue_version_id::text||':'||asset_id::text,to_jsonb(t) FROM catalog.catalogue_version_assets t WHERE printing_id=ANY(ARRAY['a00039a3-9121-49a7-b6d1-f2ec4a7d5608']::uuid[]) OR variant_id=ANY(ARRAY['7699421e-d760-4251-a090-40166235602b']::uuid[]) OR asset_id IN(SELECT id FROM catalog.assets WHERE printing_id=ANY(ARRAY['a00039a3-9121-49a7-b6d1-f2ec4a7d5608']::uuid[]) OR variant_id=ANY(ARRAY['7699421e-d760-4251-a090-40166235602b']::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['e60f305b-5ad6-4964-b6c6-636788481ca5']::uuid[]))) OR(printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['e60f305b-5ad6-4964-b6c6-636788481ca5']::uuid[])) ORDER BY scope,identity;